		{4096, ReasoningMedium},
		{4097, ReasoningMedium},
		{8192, ReasoningMedium},
		{16383, ReasoningMedium},
		// 16384 = geometric midpoint of 8192 and 32768; ties round up → high
		{16384, ReasoningHigh},
		{32768, ReasoningHigh},
