	if err != nil {
		t.Fatal(err)
	}
	if got.Policy.Value != ReasoningMedium {
		t.Fatalf("resolved effort = %q, want medium", got.Policy.Value)
	}
	if got.Source != ResolutionSourceSnapped {
		t.Fatalf("source = %q, want snapped", got.Source)
	}
	if got.Warning == "" {
